const NL = String.fromCharCode(10);
const b = $('Normalize Brief').first().json;
const cur = b.currency || '';
const safe = function (name) { try { return $(name).all().map(function (i) { return i.json; }); } catch (e) { return []; } };
const num = function (v) { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const r2 = function (n) { return Math.round(n * 100) / 100; };
const fmt = function (n) { return Math.round(n).toLocaleString('en-US'); };
const errMsg = function (e) { return typeof e === 'string' ? e : (e && e.message) ? e.message : JSON.stringify(e); };
const splitList = function (s) { return String(s || '').split(NL).join(',').split(',').map(function (x) { return x.trim(); }).filter(function (x) { return x; }); };
const top = function (list, n) { const c = {}; list.forEach(function (x) { if (x) { c[x] = (c[x] || 0) + 1; } }); return Object.keys(c).sort(function (a, z) { return c[z] - c[a]; }).slice(0, n).map(function (k) { return { name: k, count: c[k] }; }); };
const actionVal = function (actions, types) { const a = Array.isArray(actions) ? actions : []; for (let t = 0; t < types.length; t++) { const hit = a.find(function (x) { return x.action_type === types[t]; }); if (hit) { return num(hit.value); } } return 0; };
const LEADS = ['lead', 'onsite_conversion.lead_grouped', 'offsite_conversion.fb_pixel_lead'];
const PURCH = ['purchase', 'omni_purchase', 'offsite_conversion.fb_pixel_purchase'];
const sections = [];
const sources = [];
const errors = [];
const intel = {};

const metaRows = [];
safe('Meta Ads Insights').forEach(function (j) {
  if (j.error) { errors.push('Meta Ads: ' + errMsg(j.error)); }
  else if (Array.isArray(j.data)) { j.data.forEach(function (r) { metaRows.push(r); }); }
  else if (j.campaign_name) { metaRows.push(j); }
});
if (metaRows.length) {
  let sp = 0, im = 0, cl = 0, ld = 0, pu = 0;
  const rows = metaRows.map(function (r) {
    const s = num(r.spend), i = num(r.impressions), c = num(r.clicks), l = actionVal(r.actions, LEADS), p = actionVal(r.actions, PURCH);
    sp += s; im += i; cl += c; ld += l; pu += p;
    return { name: r.campaign_name, objective: r.objective, spend: s, impressions: i, ctr: num(r.ctr), cpc: num(r.cpc), cpm: num(r.cpm), leads: l, purchases: p };
  }).sort(function (a, z) { return z.spend - a.spend; }).slice(0, 10);
  const m = { spend: fmt(sp), cpm: im ? String(r2(sp / im * 1000)) : 'n/a', cpc: cl ? String(r2(sp / cl)) : 'n/a', ctr: im ? r2(cl / im * 100) + '%' : 'n/a', leads: fmt(ld), cpl: ld ? String(r2(sp / ld)) : 'n/a', purchases: fmt(pu), cpp: pu ? String(r2(sp / pu)) : 'n/a' };
  intel.meta = m;
  sources.push('Meta Ads · last 90 days');
  sections.push('META ADS - your account, last 90 days (amounts are in the ad account currency; convert if it is not ' + cur + '):' + NL +
    'Totals: spend ' + m.spend + ', CPM ' + m.cpm + ', CPC ' + m.cpc + ', CTR ' + m.ctr + ', leads ' + m.leads + ', CPL ' + m.cpl + ', purchases ' + m.purchases + ', cost per purchase ' + m.cpp + NL +
    'Top campaigns by spend:' + NL + rows.map(function (r) { return '- ' + r.name + ' [' + r.objective + ']: spend ' + fmt(r.spend) + ', CPM ' + r2(r.cpm) + ', CPC ' + r2(r.cpc) + ', CTR ' + r2(r.ctr) + '%, leads ' + r.leads + (r.leads ? ' (CPL ' + r2(r.spend / r.leads) + ')' : '') + ', purchases ' + r.purchases; }).join(NL));
}

const ttRows = [];
safe('TikTok Ads Report').forEach(function (j) {
  if (j.error) { errors.push('TikTok Ads: ' + errMsg(j.error)); }
  else if (j.code !== undefined && j.code !== 0) { errors.push('TikTok Ads: ' + (j.message || ('code ' + j.code))); }
  else if (j.data && Array.isArray(j.data.list)) { j.data.list.forEach(function (r) { ttRows.push(r.metrics || {}); }); }
});
if (ttRows.length) {
  let sp = 0, im = 0, cl = 0, cv = 0;
  const rows = ttRows.map(function (r) { const s = num(r.spend), i = num(r.impressions), c = num(r.clicks), v = num(r.conversion); sp += s; im += i; cl += c; cv += v; return { name: r.campaign_name, spend: s, ctr: num(r.ctr), cpm: num(r.cpm), cpc: num(r.cpc), conv: v }; }).sort(function (a, z) { return z.spend - a.spend; }).slice(0, 10);
  const t = { spend: fmt(sp), cpm: im ? String(r2(sp / im * 1000)) : 'n/a', cpc: cl ? String(r2(sp / cl)) : 'n/a', ctr: im ? r2(cl / im * 100) + '%' : 'n/a', conversions: fmt(cv), cpa: cv ? String(r2(sp / cv)) : 'n/a' };
  intel.tiktok = t;
  sources.push('TikTok Ads · last 30 days');
  sections.push('TIKTOK ADS - your account, last 30 days (account currency):' + NL +
    'Totals: spend ' + t.spend + ', CPM ' + t.cpm + ', CPC ' + t.cpc + ', CTR ' + t.ctr + ', conversions ' + t.conversions + ', CPA ' + t.cpa + NL +
    'Top campaigns:' + NL + rows.map(function (r) { return '- ' + r.name + ': spend ' + fmt(r.spend) + ', CPM ' + r2(r.cpm) + ', CTR ' + r2(r.ctr) + '%, conversions ' + r.conv; }).join(NL));
}

const fbAds = [];
safe('Competitor Facebook Ads').forEach(function (j) {
  if (j.error) { errors.push('Competitor Facebook ads: ' + errMsg(j.error)); return; }
  const snap = j.snapshot || {};
  const page = j.pageName || j.page_name || snap.page_name || '';
  const text = (snap.body && snap.body.text) || j.adText || j.text || '';
  if (!page && !text) { return; }
  fbAds.push({ page: page, text: String(text).slice(0, 220), cta: snap.cta_text || '', start: j.startDateFormatted || j.start_date || '' });
});
if (fbAds.length) {
  intel.competitors = top(fbAds.map(function (a) { return a.page; }), 8).map(function (x) { return { name: x.name, ads: x.count }; });
  sources.push('Meta Ad Library · competitor ads');
  sections.push('COMPETITOR ADS - currently active on Meta (Ad Library):' + NL +
    'Active ads per page: ' + intel.competitors.map(function (c) { return c.name + ' (' + c.ads + ')'; }).join(', ') + NL +
    'Sample ads:' + NL + fbAds.slice(0, 12).map(function (a) { return '- [' + a.page + (a.start ? ', since ' + a.start : '') + (a.cta ? ', CTA: ' + a.cta : '') + '] ' + a.text.split(NL).join(' '); }).join(NL));
}

const handles = splitList(b.competitor_tiktok_handles).map(function (h) { return h.replace('@', '').toLowerCase(); });
const vids = [];
safe('TikTok Competitors & Trends').forEach(function (j) {
  if (j.error) { errors.push('TikTok scraping: ' + errMsg(j.error)); return; }
  const am = j.authorMeta || {};
  const author = String(am.name || am.nickName || '').toLowerCase();
  if (!author && !j.text) { return; }
  vids.push({ author: author, plays: num(j.playCount), likes: num(j.diggCount), shares: num(j.shareCount), text: String(j.text || '').slice(0, 150), tags: (j.hashtags || []).map(function (h) { return String(h.name || '').toLowerCase(); }), music: (j.musicMeta && j.musicMeta.musicName) || '', comp: handles.indexOf(author) > -1 });
});
if (vids.length) {
  const comp = vids.filter(function (v) { return v.comp; });
  const trend = vids.filter(function (v) { return !v.comp; });
  const lines = [];
  if (comp.length) {
    const byAuthor = {};
    comp.forEach(function (v) { byAuthor[v.author] = byAuthor[v.author] || []; byAuthor[v.author].push(v); });
    intel.tiktokCompetitors = Object.keys(byAuthor).map(function (a) { const l = byAuthor[a]; return { handle: a, avgPlays: fmt(l.reduce(function (s, v) { return s + v.plays; }, 0) / l.length) }; });
    lines.push('COMPETITOR TIKTOK ACCOUNTS (recent videos):');
    Object.keys(byAuthor).forEach(function (a) { const l = byAuthor[a].sort(function (x, z) { return z.plays - x.plays; }); lines.push('- @' + a + ': ' + l.length + ' videos, avg plays ' + fmt(l.reduce(function (s, v) { return s + v.plays; }, 0) / l.length) + '. Top: "' + l[0].text + '" (' + fmt(l[0].plays) + ' plays)'); });
    sources.push('TikTok · competitor accounts');
  }
  if (trend.length) {
    const tags = [];
    trend.forEach(function (v) { v.tags.forEach(function (t) { tags.push(t); }); });
    intel.hashtags = top(tags, 10).map(function (x) { return x.name; });
    intel.sounds = top(trend.map(function (v) { return v.music; }).filter(function (m) { return m && m.toLowerCase().indexOf('original sound') === -1; }), 6).map(function (x) { return x.name; });
    lines.push('TIKTOK TRENDS for the keywords "' + b.trend_keywords + '":');
    lines.push('Top co-occurring hashtags: ' + intel.hashtags.map(function (t) { return '#' + t; }).join(', '));
    if (intel.sounds.length) { lines.push('Recurring sounds: ' + intel.sounds.join(', ')); }
    lines.push('Top videos by plays:');
    trend.sort(function (x, z) { return z.plays - x.plays; }).slice(0, 8).forEach(function (v) { lines.push('- @' + v.author + ' (' + fmt(v.plays) + ' plays, ' + fmt(v.likes) + ' likes): ' + v.text); });
    sources.push('TikTok · trends');
  }
  sections.push(lines.join(NL));
}

let marketIntel = sections.length ? sections.join(NL + NL) : 'No live data connected. Rely on market benchmarks and state that clearly in budget_notes and market_insights.';
if (errors.length) { marketIntel += NL + NL + 'DATA SOURCES THAT FAILED (ignore them, do not guess their data): ' + errors.join(' | '); }
intel.sources = sources;
intel.errors = errors;
return [{ json: { market_intel: marketIntel, intel: intel } }];

