const p = $input.first().json.output || {};
const b = $('Normalize Brief').first().json;
let intel = {};
try { intel = $('Compile Market Intel').first().json.intel || {}; } catch (e) { intel = {}; }
const ar = String(b.output_language || '') !== 'English';
const esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
const arr = function (x) { return Array.isArray(x) ? x : []; };
const L = ar ? { plan: 'الخطة الاستراتيجية للتسويق', exec: 'الملخص التنفيذي', snap: 'نظرة سريعة', budget: 'الميزانية', duration: 'المدة', months: 'شهور', market: 'السوق', goal: 'الهدف', mi: 'قراءة السوق', insights: 'أهم المؤشرات من البيانات', src: 'المصادر', bench: 'متوسطات السوق (مفيش بيانات حقيقية متوصلة)', compAds: 'إعلانات المنافسين النشطة على Meta', ttComp: 'حسابات المنافسين على TikTok', trends: 'الهاشتاجات الرائجة', sounds: 'الأصوات الرائجة', s1: '01 · التموضع والرسائل', segs: 'الشرائح المستهدفة', pain: 'نقاط الألم', pos: 'بيان التموضع', vp: 'القيمة المقدمة', diff: 'عوامل التميز', pillars: 'ركائز البراند', msgs: 'مصفوفة الرسائل', aud: 'الجمهور', msg: 'الرسالة', proof: 'الدليل', tags: 'مقترحات الشعار', tone: 'نبرة الصوت', s2: '02 · مزيج القنوات والميزانية', mix: 'توزيع الميزانية', channel: 'القناة', role: 'الدور', total: 'الإجمالي', tactics: 'دور كل قناة والتكتيكات', why: 'السبب', tac: 'التكتيكات', s3: '03 · تخطيط الحملات', camps: 'الحملات', idea: 'الفكرة', deliv: 'المخرجات', s4: '04 · الجدول الزمني والمراحل', cal: 'الجدول الزمني', mil: 'المحطات الرئيسية', owner: 'المسؤول', s5: '05 · مؤشرات الأداء والأهداف', kpis: 'مؤشرات الأداء والأهداف', kpi: 'المؤشر', stage: 'المرحلة', target: 'المستهدف', meas: 'طريقة القياس', freq: 'التكرار', risks: 'المخاطر', mit: 'التعامل', next: 'الخطوات التالية', wrap: 'الختام', m: 'ش', w: 'أ' } : { plan: 'Strategic Marketing Plan', exec: 'Executive summary', snap: 'Snapshot', budget: 'Budget', duration: 'Duration', months: 'months', market: 'Market', goal: 'Goal', mi: 'Market intelligence', insights: 'Data-driven insights', src: 'Sources', bench: 'Market benchmarks (no live data connected)', compAds: 'Active competitor ads on Meta', ttComp: 'Competitor TikTok accounts', trends: 'Trending hashtags', sounds: 'Trending sounds', s1: '01 · Positioning & messaging', segs: 'Target segments', pain: 'Pain points', pos: 'Positioning statement', vp: 'Value proposition', diff: 'Differentiators', pillars: 'Brand pillars', msgs: 'Messaging matrix', aud: 'Audience', msg: 'Message', proof: 'Proof point', tags: 'Tagline options', tone: 'Tone of voice', s2: '02 · Channel mix & budget', mix: 'Budget allocation', channel: 'Channel', role: 'Role', total: 'Total', tactics: 'Channel roles & tactics', why: 'Why', tac: 'Tactics', s3: '03 · Campaign planning', camps: 'Campaigns', idea: 'Big idea', deliv: 'Deliverables', s4: '04 · Calendar & milestones', cal: 'Campaign calendar', mil: 'Key milestones', owner: 'Owner', s5: '05 · KPIs & targets', kpis: 'KPIs & targets', kpi: 'KPI', stage: 'Stage', target: 'Target', meas: 'Measurement', freq: 'Frequency', risks: 'Risks', mit: 'Mitigation', next: 'Next steps', wrap: 'Wrap-up', m: 'M', w: 'W' };
const budget = Number(b.total_budget) || 0;
const cur = esc(b.currency || '');
const money = function (n) { return Math.round(n).toLocaleString('en-US') + ' ' + cur; };
const pos = p.positioning || {};
const channels = arr(p.channel_mix).slice();
const pctSum = channels.reduce(function (s, c) { return s + (Number(c.budget_percent) || 0); }, 0) || 1;
channels.forEach(function (c) { c.pct = (Number(c.budget_percent) || 0) * 100 / pctSum; c.amount = budget * c.pct / 100; });
channels.sort(function (x, y) { return y.pct - x.pct; });
const months = Number(b.duration_months) || 3;
const totalWeeks = Math.max(4, Math.round(months * 4.345));
const list = function (items) { return '<ul>' + arr(items).map(function (i) { return '<li>' + esc(i) + '</li>'; }).join('') + '</ul>'; };
const chips = function (items) { return '<div class="chips">' + arr(items).map(function (i) { return '<span class="chip">' + esc(i) + '</span>'; }).join('') + '</div>'; };
const slides = [];
const slide = function (kicker, title, body) { slides.push('<section class="slide"><div class="kicker">' + esc(kicker) + '</div><h2>' + esc(title) + '</h2><div class="body">' + body + '</div><footer><span>' + esc(b.brand_name) + ' · ' + esc(L.plan) + '</span><span class="num"></span></footer></section>'); };
const tile = function (label, value) { return '<div class="tile"><div class="tl">' + esc(label) + '</div><div class="tv">' + esc(value) + '</div></div>'; };
const table = function (heads, rows) { return '<table><thead><tr>' + heads.map(function (h) { return '<th>' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>' + rows.map(function (r) { return '<tr>' + r.map(function (c) { return '<td>' + c + '</td>'; }).join('') + '</tr>'; }).join('') + '</tbody></table>'; };

slides.push('<section class="slide cover"><div class="kicker">' + esc(L.plan) + '</div><h1>' + esc(b.brand_name) + '</h1><p class="lead">' + esc(b.industry) + ' · ' + esc(b.target_market) + '</p><p class="meta">' + esc(b.start_date) + ' · ' + months + ' ' + esc(L.months) + '</p></section>');
slide(L.snap, L.exec, '<p class="lead">' + esc(p.executive_summary) + '</p><div class="tiles">' + tile(L.budget, money(budget)) + tile(L.duration, months + ' ' + L.months) + tile(L.market, b.target_market) + tile(L.goal, b.goal_target || b.objectives) + '</div>');

const liveTiles = [];
if (intel.meta) { liveTiles.push(tile('Meta CPM', intel.meta.cpm), tile('Meta CPC', intel.meta.cpc), tile('Meta CTR', intel.meta.ctr), tile('Meta CPL', intel.meta.cpl)); }
if (intel.tiktok) { liveTiles.push(tile('TikTok CPM', intel.tiktok.cpm), tile('TikTok CPC', intel.tiktok.cpc), tile('TikTok CTR', intel.tiktok.ctr), tile('TikTok CPA', intel.tiktok.cpa)); }
const side = [];
if (arr(intel.competitors).length) { side.push('<div class="card"><div class="lbl">' + esc(L.compAds) + '</div>' + chips(intel.competitors.map(function (c) { return c.name + ' · ' + c.ads; })) + '</div>'); }
if (arr(intel.tiktokCompetitors).length) { side.push('<div class="card"><div class="lbl">' + esc(L.ttComp) + '</div>' + chips(intel.tiktokCompetitors.map(function (c) { return '@' + c.handle + ' · ' + c.avgPlays; })) + '</div>'); }
if (arr(intel.hashtags).length) { side.push('<div class="card"><div class="lbl">' + esc(L.trends) + '</div>' + chips(intel.hashtags.map(function (h) { return '#' + h; })) + '</div>'); }
if (arr(intel.sounds).length) { side.push('<div class="card"><div class="lbl">' + esc(L.sounds) + '</div>' + chips(intel.sounds) + '</div>'); }
slide(L.mi, L.mi, (liveTiles.length ? '<div class="tiles">' + liveTiles.join('') + '</div>' : '') + '<div class="grid ' + (side.length ? 'g2' : '') + '"><div class="card"><div class="lbl">' + esc(L.insights) + '</div>' + list(p.market_insights) + '<p class="small">' + esc(L.src) + ': ' + esc(arr(intel.sources).length ? intel.sources.join(' · ') : L.bench) + '</p></div>' + (side.length ? '<div class="stack">' + side.join('') + '</div>' : '') + '</div>');

slide(L.s1, L.segs, '<div class="grid g3">' + arr(pos.target_segments).map(function (s) { return '<div class="card"><h3>' + esc(s.name) + '</h3><p>' + esc(s.description) + '</p><div class="lbl">' + esc(L.pain) + '</div>' + list(s.pain_points) + '</div>'; }).join('') + '</div>');
